/** A00-R01-REGMOV: cabecera del movimiento y hasta cinco importes (A00-R01-ELE-CVEIMP OCCURS 5). */
public record MovimientoContable(
        int funcion,                 // 9(02) COMP: 1 = registrar, 99 = fin de archivo lógico
        int formato,
        int sistema,                 // 500 o 264
        int producto,                // REDEFINES: TIPOCREDITO / TIPO-PROD comparten los mismos bytes
        int instrumento,             // REDEFINES: PORTAFOLIO / FONDO
        int servicioAlerta,
        int tipoMovimiento,
        int agrupDesvProd, int agrupDesvInst,
        int sirhDesvio,
        int libroContable,
        List<Importe> importes,      // solo los elementos con CVETRAN distinto de cero
        /* ... resto de campos de A00-R01-REGMOV (sucursal, caja, moneda, fechas) ... */
        int moneda, int sucTran, int sucInic, int cajaTran, int tipoProc,
        int origen, int status, long fecUltMov, long autS151) {

    /** Elemento de A00-R01-ELE-CVEIMP. */
    public record Importe(int cveTran,          // 9(06) COMP
                          int indLey,
                          int esqCon,           // REDEFINES A00-R01-TM
                          BigDecimal importe,   // 9(16)V99 COMP -> escala 2
                          int cveDesvio,
                          int guiaDesvio) {}

    /** PERFORM ... VARYING W77-IND FROM 1 BY 1 UNTIL W77-IND > 5 OR A00-R01-CVETRAN(W77-IND) = 0 */
    public static List<Importe> vigentes(Importe[] ocurrencias) {
        return Arrays.stream(ocurrencias)
                .limit(5)
                .takeWhile(i -> i.cveTran() != 0)
                .toList();
    }
}

