@Component
@StepScope
@RequiredArgsConstructor
public class FraudeItemProcessor implements ItemProcessor<MovimientoContable, List<RegistroFraude>> {

    private final CatalogoFraudes catalogo;   // WKS-TABLA-FRAUD, catálogo S080 1688
    private final DesS500Repository descripciones;

    @Override
    public List<RegistroFraude> process(MovimientoContable m) {
        // El fuente escribe: SISTEMA = 500 AND TIPO-PROC = 40 OR 41 OR 42 OR 43.
        // COBOL evalúa AND antes que OR: (SISTEMA = 500 AND TIPO-PROC = 40) OR TIPO-PROC = 41 OR 42 OR 43.
        boolean excluido = (m.sistema() == 500 && m.tipoProc() == 40)
                || m.tipoProc() == 41 || m.tipoProc() == 42 || m.tipoProc() == 43;
        if (excluido) return null;

        if (m.sistema() != 500 || m.funcion() != 1 || m.status() != 1
                || !(m.origen() == 1 || m.origen() == 3)) {
            return null;
        }
        List<RegistroFraude> salida = m.importes().stream()                // ya cortada en el primer CVETRAN = 0
                .filter(imp -> catalogo.marcado(imp.cveTran()))
                .map(imp -> RegistroFraude.de(m, imp, descripciones.find(m)))   // 400022-CARGA-DATOS-FRAUD
                .toList();
        return salida.isEmpty() ? null : salida;
    }
}

@Component
@RequiredArgsConstructor
public class CatalogoFraudes {

    private static final int TAMANO_TABLA = 5000;      // WKS-TAB-FRAUD-500 OCCURS 5000
    private final CatalogoS080Client s080;             // L710_CONSUL_DETALLE, catálogo 1688
    private volatile Set<Integer> marcados = Set.of();

    /** 025500-CATALOGO-FRAUDES: carga paginada de 10 en 10 hasta RESULT distinto de 0/1. */
    @PostConstruct
    void cargar() {
        marcados = s080.detalle(151, 52, 1688).stream()
                .filter(r -> r.dato(11) == 1)
                .map(r -> r.dato(1))
                .collect(Collectors.toUnmodifiableSet());
    }

    /** 400040-MUEVE-DATOS-FRAUD: IF WKS-TAB-FRAUD-500(CVETRAN) = 1. */
    public boolean marcado(int cveTran) {
        if (cveTran < 1 || cveTran > TAMANO_TABLA) {
            // En el MCP un subíndice fuera de 1..5000 provoca INVALID INDEX y aborta la tarea.
            log.warn("CVETRAN {} fuera del rango de la tabla de fraudes", cveTran);
            return false;
        }
        return marcados.contains(cveTran);
    }
}
